"""Build traceable report content and editable slide content from experiment artifacts."""
import html,json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'deliverables';BUILD=ROOT/'artifacts/document_build'

def main():
    OUT.mkdir(exist_ok=True);BUILD.mkdir(exist_ok=True)
    results=json.loads((ROOT/'artifacts/models/v1/results.json').read_text(encoding='utf-8'))
    rows=results['models'];chosen={k:next(r for r in rows if r['kind']==k and r['id']==v) for k,v in results['selected'].items()}
    sections=[]
    def section(title,paragraphs=(),table=None,image=None):sections.append({'title':title,'paragraphs':list(paragraphs),'table':table,'image':image})
    title='Phân tích dữ liệu tin đăng và xây dựng hệ thống ước tính giá rao bán nhà ở tại TP Hồ Chí Minh bằng Apache Spark'
    section('Tóm tắt',[
        'Đồ án xây dựng một quy trình xử lý tin đăng nhà riêng và căn hộ tại TP.HCM, từ kiểm tra nguồn, phân loại giao dịch, kiểm tra chéo giá và diện tích đến huấn luyện mô hình và phục vụ kết quả qua web. Mục tiêu là ước tính giá rao bán từ thuộc tính nhà ở và trình bày thống kê của tập tin được chọn. Giá nguồn chưa được xác minh bằng giao dịch thực tế.',
        'Nguồn oceanNG/vietnam-real-estates có 3.500.744 dòng và 19 trường. Trong đó, 1.122.870 dòng có nhãn tỉnh Hồ Chí Minh và loại hình nhà hoặc căn hộ. Apache Spark xử lý toàn bộ phạm vi này. Sau kiểm tra chất lượng, loại mẫu từng kiểm tra, chuẩn hóa địa bàn và xử lý đăng lại, tập nghiên cứu gồm 133.779 tin trong giai đoạn 06/2025–03/2026.',
        'Thực nghiệm gồm baseline trung vị giá train theo loại hình và khu vực, LinearRegression, RandomForest và GBT. Mỗi thuật toán có phương án riêng từng loại hình và phương án chung. Tiền xử lý chỉ học trên train. Mô hình được chọn theo MAE validation trước khi mở đánh giá test. LinearRegression riêng từng loại hình đạt MAE test 2,950 tỷ VND cho nhà và 1,395 tỷ VND cho căn hộ. MAE giảm tương ứng 36,7% và 58,5% so với baseline.',
        'Sản phẩm web có tổng quan, bảng thị trường, bản đồ 22 nhóm địa bàn lịch sử, biểu mẫu ước tính, đánh giá mô hình và giải thích phương pháp. Hệ thống chạy trên máy hoặc LAN với FastAPI và Next.js. Kết quả mô tả tập tin nguồn được chọn, chịu ảnh hưởng của giá cực cao, sai số nguồn và trùng tài sản chưa phát hiện. Báo cáo này hoàn thiện nội dung kỹ thuật; nhóm cần xác nhận tên đề tài với giảng viên và bổ sung thông tin lớp, nhật ký, đóng góp thực tế trước khi nộp.'
    ])
    section('1 Giới thiệu bài toán và yêu cầu môn học',[
        'Tin đăng bất động sản cung cấp thông tin về giá, diện tích, vị trí và cấu trúc nhà ở nhưng chất lượng không đồng đều. Một tin có thể chứa giá trả trước, giá theo mét vuông, nhiều sản phẩm hoặc vừa bán vừa cho thuê. Lấy mọi giá số dương làm nhãn sẽ tạo dữ liệu huấn luyện sai. Vì vậy, vấn đề chính của đồ án là xây dựng tập nghiên cứu có điều kiện rõ ràng trước khi so sánh mô hình.',
        'Đầu vào suy luận gồm loại hình, diện tích, quận/huyện tham chiếu và các thuộc tính tùy chọn. Đầu ra là một mức giá rao bán điển hình, dải tham khảo theo sai số validation và cảnh báo khi đầu vào ít được dữ liệu train hỗ trợ. Nhóm không đặt mục tiêu xác minh pháp lý tài sản hoặc dự đoán giá giao dịch đã chốt.',
        'Theo tài liệu Kế hoạch Đồ án môn học Nhập môn Big Data của HUIT trong hồ sơ, bài làm cần có bài toán thực tế, nguồn và quy mô dữ liệu, cấu trúc dữ liệu, ETL, ít nhất một công nghệ Big Data, thực nghiệm và đánh giá, sản phẩm minh họa, báo cáo Word, slide và mã nguồn. Báo cáo phải có cơ sở lý thuyết, ứng dụng và trực quan, kết luận, tài liệu tham khảo, phụ lục, nhật ký và đóng góp thành viên. Web là cách triển khai phần minh họa nhóm đã lựa chọn.',
        'Apache Spark SQL và MLlib đáp ứng phần công nghệ Big Data. Thực nghiệm hiện chạy local[4] với driver 4 GB trên một máy; đây chưa phải phép đo hiệu năng cluster nhiều máy. Phạm vi nghiên cứu giữ nhà riêng và căn hộ chung cư tại 22 nhóm địa bàn TP.HCM trước hợp nhất năm 2025. Những mở rộng như crawler, GPS, KMeans hoặc địa bàn phường hiện hành không phải điều kiện hoàn thành phiên bản này.'
    ])
    section('2 Cơ sở lý thuyết',[
        'Apache Spark cung cấp cơ chế xử lý dữ liệu bằng các phép biến đổi và hành động. DataFrame biểu diễn dữ liệu có schema, hỗ trợ lọc, join, groupBy và cửa sổ. Spark thực hiện tính toán khi có hành động như count hoặc ghi dữ liệu. Trong đồ án, Spark SQL chuẩn hóa trường, tính cờ kiểm tra và phân tuyến các bản ghi. Dữ liệu nguồn và kết quả được lưu bằng Parquet để giữ kiểu dữ liệu và giảm chi phí đọc các cột cần thiết.',
        'Pipeline MLlib gắn các bước tiền xử lý với bộ hồi quy, giúp dùng cùng phép biến đổi khi huấn luyện và suy luận. Imputer xử lý biến số thiếu bằng trung vị học từ train. StringIndexer và OneHotEncoder biểu diễn địa bàn, phường và dự án, có chế độ xử lý nhóm chưa thấy. StandardScaler chuẩn hóa đặc trưng mà không dịch tâm để giữ biểu diễn thưa.',
        'LinearRegression học quan hệ tuyến tính giữa đặc trưng và log giá, với regularization để hạn chế hệ số quá lớn. RandomForest lấy trung bình dự đoán của nhiều cây, hỗ trợ quan hệ phi tuyến. GBT bổ sung cây theo từng vòng để giảm sai số của tổ hợp trước đó. Các cấu hình được cố định trước khi xem kết quả, thay vì tìm kiếm tham số dựa trên test.',
        'Với giá thật y và dự đoán p, MAE là trung bình |p−y|; RMSE là căn bậc hai của trung bình (p−y)². R² bằng 1−SSE/SST và có thể âm. MAPE là trung bình |p−y|/y, còn median APE là trung vị tỷ lệ này. MAPE nhạy với giá rất thấp; RMSE nhạy với sai số rất lớn. Vì vậy, báo cáo trình bày đồng thời các chỉ số, số mẫu và phân tích đuôi sai số.',
        'Mục tiêu hồi quy là log(y). Đầu ra tiền tệ được tính exp(log prediction), thể hiện mức giá điển hình và không tự được coi là ước lượng trung bình không chệch. Với q là phân vị 90% của |log(y/p)| trên validation, dải tham khảo là [p×exp(−q), p×exp(q)]. Tỷ lệ bao phủ phải đo trên test; phân vị validation không bảo đảm bao phủ 90% cho dữ liệu tương lai.'
    ])
    section('3 Nguồn dữ liệu và khả năng truy vết',[
        'Dữ liệu dùng từ kho oceanNG/vietnam-real-estates trên Hugging Face, revision 6f68fe87be7577afb03e38c535bd882d242ba26d. Mười shard Parquet đã tải và xác minh checksum. Manifest lưu repository, revision, tên file và thông tin đối chiếu. Nhóm không chạy crawler để tạo tập thực nghiệm này, và không gọi dữ liệu lưu sẵn là dữ liệu thị trường trực tiếp.',
        'Các trường mô tả gồm name, description, property_type_name, province_name, district_name, ward_name, street_name và project_name. Các trường số gồm price, area, floor_count, frontage_width, house_depth, road_width, bedroom_count và bathroom_count. Các trường còn lại là house_direction, balcony_direction và published_at. Giá nguồn cần chuyển từ chuỗi sang số với kiểm tra cú pháp và hữu hạn; dữ liệu thiếu vẫn được lưu và không tự gán nhãn bằng 0.',
        'Nhãn tỉnh và loại hình từ nguồn chỉ xác định phạm vi khảo sát ban đầu. Nội dung mô tả được dùng để kiểm tra giao dịch, tổng giá, loại diện tích và công năng. Giá và địa chỉ trong tin chưa được đối chiếu với chủ sở hữu hoặc cơ quan giao dịch. Trường project_name có thể thiếu, viết khác nhau hoặc thuộc dự án chưa có trong train.',
        'Các manifest, mẫu review, snapshot quy tắc, mã nguồn, lựa chọn mô hình và kết quả máy đọc được giữ theo phiên bản. Đầu ra ETL, cohort và mô hình từ chối ghi đè. Gói demo không cần chứa mô tả đầy đủ, điện thoại hoặc địa chỉ đường cụ thể. Bảng phục vụ web chỉ gồm loại hình, mã và nhãn quận, tháng đăng, diện tích, giá và đơn giá.'
    ],[['Phạm vi','Số dòng'],['Toàn nguồn','3.500.744'],['Nhãn tỉnh Hồ Chí Minh','1.357.526'],['Nhà và căn hộ trong tỉnh nguồn','1.122.870'],['Sau bỏ hai bản ghi nguồn giống hệt','1.122.868'],['Ứng viên kiểm tra chéo v4','149.975'],['Tập nghiên cứu cuối','133.779']])
    section('4 Nhận diện giao dịch và kiểm tra chất lượng',[
        'Quy tắc nhận diện giao dịch xem đồng thời tiêu đề và mô tả, đơn vị giá và ngữ cảnh. Các tín hiệu thuê theo tháng, đặt cọc, sang nhượng hoặc tổng giá bán được xét riêng. Khi tín hiệu mâu thuẫn hoặc chưa xác định, hệ thống giữ trạng thái uncertain và cách ly khỏi hồi quy. Một từ bán xuất hiện trong mô tả không đủ để xác định tin bán.',
        'Lớp kiểm tra chéo yêu cầu tổng giá trong trường nguồn được nội dung hỗ trợ, có xét đơn vị triệu/tỷ và độ lệch định lượng nhỏ. Hệ thống phát hiện giá trả trước, vốn ban đầu, giá khởi điểm, dải giá hoặc nhiều sản phẩm không có tài sản chính rõ ràng. Với căn hộ, diện tích cần phù hợp diện tích căn hộ; với nhà, cần diện tích đất được hỗ trợ. Diện tích sàn không được tự đổi thành diện tích đất, và tích ngang×sâu chỉ làm tín hiệu đối chiếu khi ngữ cảnh phù hợp, không dùng điền nhãn.',
        'Công năng được kiểm tra để loại nhóm chỉ có đất, tòa nhà kinh doanh hoặc officetel chưa rõ nhà ở. Các giá trị không hữu hạn, giá hoặc diện tích không dương, mâu thuẫn diện tích chính hoặc phép tính giá sai được cách ly. Các quy tắc này giữ hồ sơ lý do loại thay vì xóa âm thầm, cho phép kiểm tra lại quyết định ETL.',
        'Quy tắc giao dịch frozen có SHA256 a2b7d760d9507f807edfbae6d414b575235ef399376581d018fda35b01a35b8e. Quality cross-field-v4-provisional có SHA256 715b5b317087f9f347813d029f6114df7743dc3374dc158d46b9f5d58beb92d4. Bản ETL cuối etl_v4 hoàn tất sau 503,59 giây, ghi và đọc kiểm tra đủ số bản ghi. Thời gian chỉ mô tả lần chạy này trên một máy, chưa phải benchmark tổng quát.',
        'Trong 149.975 ứng viên, có 22.789 tin nhà và 127.186 tin căn hộ. Các nhóm thuê và cách ly được lưu riêng cùng cờ lý do. Do bộ lọc nghiêm ngặt và tỷ lệ giữ thấp, phân bố sau lọc khác toàn bộ nguồn. Sự thay đổi này là thiên lệch lựa chọn cần được nêu khi đọc thống kê.'
    ])
    section('5 Quy trình kiểm chứng mẫu',[
        'Quy trình review tách phần đọc nội dung khỏi phần dự đoán quy tắc. Mẫu mới có seed, mã nhận diện ổn định và loại tất cả ID đã xuất hiện trong các lượt trước. Mỗi dòng ghi giao dịch, loại diện tích, mức hỗ trợ giá và diện tích, phạm vi công năng, ghi chú và phương thức gán nhãn. Chỉ tính chỉ số sau khi toàn bộ dòng cần thiết đã có nhãn.',
        'Qua các lượt v1–v5, hệ thống lưu 800 nhãn tham chiếu do AI đọc nội dung. Các lượt hiệu chỉnh và đánh giá được ghi riêng. Khi một lượt mới cho thấy hạn chế, quy tắc được sửa rồi kiểm tra bằng mẫu mới của phiên bản tiếp theo. Quy tắc đã đánh giá không được sửa dựa trên cùng mẫu rồi công bố như đánh giá độc lập.',
        'Mẫu v5 gồm 100 ứng viên chưa từng được kiểm tra, dùng quality v4 đã đóng băng. Có 99/100 tin được nội dung hỗ trợ giá và diện tích, và 98/100 được hỗ trợ cả giao dịch, giá, diện tích và phạm vi. Ngưỡng nghiên cứu xác định trước là tỷ lệ quan sát ít nhất 95% trên ít nhất 80 mẫu. Kết quả đạt ngưỡng theo tỷ lệ điểm, không đạt hoặc khẳng định cận dưới Wilson 95%.',
        'Khoảng Wilson 95% của 98/100 là 93,00%–99,45%. Mẫu chỉ có 14 tin nhà và 86 tin căn hộ; kết quả theo loại hình lần lượt 14/14 và 84/86. Số tin nhà ít làm kết luận riêng nhóm nhà còn yếu. Hai trường hợp còn lại liên quan mô tả nhiều mã căn và dải giá hoặc danh mục nhiều sản phẩm thiếu tài sản chính rõ ràng.',
        'Nhãn AI không phải ground truth chuyên gia, không xác minh tính thật của tin đăng và không chứng nhận chất lượng toàn tập. Mọi ID từng được đọc trong khảo sát hoặc review đều được loại khỏi thực nghiệm giá: danh sách có 2.480 ID, trong đó 428 xuất hiện trong tập ứng viên cuối. Cách làm này giảm việc đánh giá mô hình trên các dòng đã tham gia thiết kế quy tắc. Một lượt kiểm tra người độc lập là hướng mở rộng sau bản kỹ thuật hiện tại.'
    ],[['Lượt mới','Số mẫu','Hỗ trợ giá và diện tích','Hỗ trợ cả phạm vi'],['v3 / quality v2','100','96/100','83/100'],['v4 / quality v3','100','97/100','94/100'],['v5 / quality v4','100','99/100','98/100']])
    section('6 Địa bàn và xử lý tin đăng lại',[
        'Tên quận/huyện và phường được chuẩn hóa Unicode NFC, tiền tố và biểu diễn mã. Ghép mã địa danh sử dụng Vietnamese Provinces Database v2.4.1, commit fc33b7411ec4e3697817fab8118718a8d39ef090, giấy phép MIT. Quận 2, Quận 9 và Thủ Đức cũ được gộp về nhóm thành phố Thủ Đức. Các địa danh cùng tên được phân biệt theo vùng không gian và tham chiếu cấp trên.',
        'Bản đồ dùng geoBoundaries VNM-ADM2-81297802, thể hiện ranh giới năm 2020, nguồn OCHA ROAP và Government of Vietnam, giấy phép CC BY 3.0 IGO. Ranh giới được chọn và hợp nhất thành 22 nhóm nghiên cứu, kiểm tra hình học hợp lệ bằng Shapely. Bản đồ không cung cấp tọa độ từng nhà và không mô tả địa giới pháp lý hiện hành năm 2026.',
        'Trong 149.975 ứng viên trước loại review, có 123.516 ghép được quận và phường theo tham chiếu, 26.020 ghép được quận nhưng thiếu phường, 439 ghép quận nhưng tên phường khác thời kỳ hoặc chưa biết. Hệ thống giữ trạng thái ghép và trường nguồn, không gán phường giả. Trường phường thiếu được pipeline mô hình xử lý như dữ liệu thiếu.',
        'Hai bản ghi nguồn giống hoàn toàn được loại trước. Để giảm tin đăng lại xuyên thời gian, hệ thống tạo hash từ toàn văn tiêu đề và mô tả đã chuẩn hóa, bỏ biểu diễn số tiền và số liên hệ, kèm loại hình, địa bàn và diện tích. Mỗi nhóm giữ bản có thời gian đăng sớm nhất; khi bằng thời gian, source_record_id làm thứ tự ổn định.',
        'Trước xử lý có 2.734 nhóm proxy đăng lại xuất hiện ở nhiều giai đoạn, sau xử lý còn 0 nhóm proxy xuyên split. Điều này chỉ đúng cho khóa trùng toàn văn đã định nghĩa. Cùng tài sản đổi nội dung hoặc được nhiều môi giới đăng vẫn có thể tồn tại trong nhiều tập. Việc giữ bản sớm nhất cũng thay đổi số lượng tin theo tháng, nên biểu đồ thời gian thể hiện tập sau xử lý, không phải lượng giao dịch.'
    ])
    section('7 Chia tập và phòng ngừa rò rỉ',[
        'Tập core_v1 được chia theo tháng đăng: train từ 06 đến 11/2025, validation tháng 12/2025, test từ 01 đến 03/2026. Không random split các tin xuyên thời gian. Sau loại mẫu review và xử lý đăng lại, có 133.779 tin. Số lượng ở bảng dưới là số bản ghi giữ lại, không phải số tài sản duy nhất đã xác minh.',
        'Các bước học thống kê gồm trung vị điền thiếu, mã hóa danh mục và chuẩn hóa đều fit trên train. Baseline và danh mục phường/dự án cho đầu vào web cũng chỉ lấy từ train. Giá/m² được phép dùng trong thống kê thị trường, nhưng bị loại khỏi đặc trưng hồi quy vì là phép tính trực tiếp từ target.',
        'Tên và mô tả được dùng ở kiểm tra chất lượng, không đưa vào đặc trưng dự đoán giá. Thời gian đăng không làm đặc trưng. Quy tắc kiểm tra chéo sử dụng giá nguồn để chọn cohort, nên vẫn tạo thiên lệch lựa chọn; việc loại giá/m² khỏi features không loại được thiên lệch này. Bộ dữ liệu và điều kiện chọn được công bố để người đọc đánh giá giới hạn.',
        'Sau khi fit, pipeline được lưu rồi nạp lại chính artifact trước tính validation. Chọn mô hình theo MAE validation riêng cho từng loại hình, có xét cả baseline và mô hình chung. selection.json được ghi trước đánh giá test, với test_used_for_selection=false. Không thay cấu hình, cắt giá test hoặc hiệu chỉnh target test để cải thiện điểm.'
    ],[['Tập','Giai đoạn','Nhà','Căn hộ','Tổng'],['Train','06–11/2025','12.192','65.856','78.048'],['Validation','12/2025','2.570','15.316','17.886'],['Test','01–03/2026','4.705','33.140','37.845']])
    section('8 Đặc trưng và cấu hình thực nghiệm',[
        'Đặc trưng bắt buộc là loại hình, diện tích và district_code. Các đặc trưng tùy chọn gồm ward_code, project_name, bedroom_count, bathroom_count, floor_count, frontage_width, house_depth và road_width. Diện tích được biến đổi log. Mô hình chung thêm loại hình, mô hình riêng chỉ học một loại. Không dùng thời điểm, giá gốc, đơn giá hoặc văn bản có giá làm đầu vào hồi quy.',
        'Biến số tùy chọn không hữu hạn, không dương hoặc vượt giới hạn cú pháp được chuyển thiếu trong features: tối đa 50 phòng, 100 tầng, 1.000 m cho các chiều dài. Đây là giới hạn xử lý đầu vào được xác định trước, không phải kết quả tối ưu trên target. Trường nguồn trong cohort được giữ để truy vết. Có chỉ báo thiếu; biến giá trị thiếu hoàn toàn trong train được bỏ khỏi bước imputation, chỉ báo vẫn được giữ.',
        'Pipeline dùng median imputation, StringIndexer handleInvalid=keep, OneHotEncoder giữ nhóm chưa thấy và StandardScaler không dịch tâm. Ba bộ hồi quy cùng dự đoán log giá. Cấu hình cố định nhằm chạy được trên tài nguyên hiện tại; đồ án không tuyên bố đã tìm mô hình tốt nhất trong mọi cấu hình.',
        'Có chín pipeline: ba thuật toán cho nhà, ba cho căn hộ và ba mô hình chung. Baseline là trung vị tổng giá train theo loại hình và quận khi có ít nhất 20 tin; nhóm ít mẫu dùng trung vị theo loại hình. Tổng thời gian lần chạy huấn luyện, lưu/nạp và đánh giá là 187,60 giây, không tính khảo sát, ETL hoặc tải dữ liệu.'
    ],[['Phương án','Cấu hình trước thực nghiệm'],['LinearRegression','regParam 0,05; maxIter 80'],['RandomForest','30 cây; maxDepth 7; minInstancesPerNode 10'],['GBT','30 vòng; maxDepth 5; stepSize 0,1; minInstancesPerNode 10'],['Seed cây','20261012'],['Tiêu chí chọn','MAE validation theo VND'],['Môi trường','Spark 3.5.7; Python 3.11; Java 17; local[4]; driver 4 GB']])
    for kind,label in [('house','nhà'),('apartment','căn hộ')]:
        table=[['Phương án','MAE val','RMSE val','MAE test','RMSE test','R² test']]
        for r in rows:
            if r['kind']==kind:table.append([r['id']]+[f"{r[s][m]/1e9:.3f}" for s,m in [('validation','mae_vnd'),('validation','rmse_vnd'),('test','mae_vnd'),('test','rmse_vnd')]]+[f"{r['test']['r2']:.3f}"])
        c=chosen[kind];base=next(r for r in rows if r['kind']==kind and r['id']=='baseline')
        section(('9' if kind=='house' else '10')+' Kết quả mô hình '+label,[
            f"Phương án được chọn là {c['id']} theo MAE validation. Trên test gồm {c['test']['count']:,} tin, MAE là {c['test']['mae_vnd']/1e9:.3f} tỷ VND, RMSE là {c['test']['rmse_vnd']/1e9:.3f} tỷ VND, R² là {c['test']['r2']:.3f}. MAE thấp hơn baseline {(1-c['test']['mae_vnd']/base['test']['mae_vnd'])*100:.1f}%. Đơn vị MAE và RMSE trong bảng là tỷ VND; dấu chấm thể hiện phần thập phân trong các bảng tự xuất từ JSON.",
            f"MAPE test là {c['test']['mape']*100:.2f}% và median APE là {c['test']['median_ape']*100:.2f}%. Hai chỉ số phần trăm mô tả khác nhau: median APE cho biết một nửa mẫu có tỷ lệ sai số thấp hơn mức này, không phải cam kết sai số tối đa cho từng nhà. Test được dùng để báo cáo sau khi chốt lựa chọn, không làm căn cứ chọn lại mô hình.",
            ('Sai số nhà có đuôi rất lớn. Mười sai số lớn nhất chiếm 92,20% tổng sai số bình phương. Hai giá nguồn lớn nhất trong nhóm sai số là 800 và 850 tỷ VND, trên diện tích 948 và 915 m². Mô hình dự đoán thấp hơn nhiều. Chưa xác minh tính thật của các tin này, và không loại chúng trên test để tăng chỉ số.' if kind=='house' else 'Validation căn hộ có RMSE khoảng 43,313 tỷ VND và R² khoảng 0,021, dù MAE khoảng 1,503 tỷ VND. Đây là dấu hiệu ảnh hưởng rất mạnh của giá nguồn cực cao. Trên test, mười sai số lớn nhất chiếm 42,47% SSE; có hai tin giá nguồn 360 tỷ VND trên 407 m². Chưa xác minh nguồn và không diễn giải điểm test tốt hơn như bằng chứng mô hình ổn định mọi giai đoạn.'),
            'Các bảng test_by_district và test_by_price phân tích chỉ số theo quận và các khoảng giá cố định dưới 3, 3–6, 6–12, từ 12 tỷ VND. Nhóm ít mẫu cần đọc cùng count. Scatter dùng 300 mẫu theo hash ID ổn định cho mỗi loại hình để minh họa, không thay thế chỉ số tính trên toàn bộ test. Toàn bộ kết quả validation/test, cấu hình và artifact được lưu trong artifacts/models/v1.'
        ],table)
    section('11 Dải tham khảo và giới hạn mô hình',[
        'Dải tham khảo dùng phân vị 90% của sai số log tuyệt đối trên validation. Bán kính log là 0,452170 cho nhà và 0,316363 cho căn hộ. Khi suy luận, mô hình nhân mức giá điển hình với exp(±bán kính). Đây là cách cung cấp ngữ cảnh sai số phù hợp với mô hình log giá, không phải khoảng tin cậy của giá trị thật đã được xác minh.',
        f"Tỷ lệ giá nguồn test nằm trong dải là {results['bands']['house']['test_empirical_coverage']*100:.2f}% với nhà và {results['bands']['apartment']['test_empirical_coverage']*100:.2f}% với căn hộ. Coverage căn hộ thấp hơn mức phân vị validation, cho thấy khác biệt thời kỳ và phân bố. Giao diện công bố tỷ lệ thực đo riêng từng loại, không gắn nhãn bảo đảm 90%.",
        'API kiểm tra loại hình và khu vực phải được train hỗ trợ, diện tích hữu hạn trong (0; 10.000] m². Phường cung cấp phải thuộc danh mục train của đúng quận và loại hình. Dự án chưa thấy vẫn có thể ước tính qua nhóm danh mục chưa thấy và đi kèm cảnh báo. Diện tích ngoài khoảng phân vị 1%–99% train có cảnh báo ngoại suy.',
        'Nhà ở được mô tả bởi nhiều yếu tố chưa có: chất lượng xây dựng, tầng căn hộ, pháp lý, tình trạng nội thất, hướng và vi vị trí. Dữ liệu nguồn thiếu thông tin hoặc dùng thông thủy/tim tường không nhất quán. Giá rất thấp có thể làm MAPE biến động và giá cực cao làm RMSE tăng. Các giới hạn này cần được trình bày trong báo cáo và màn hình, thay vì dùng một chỉ số duy nhất để khẳng định độ chính xác.'
    ])
    section('12 Kiến trúc và sản phẩm web',[
        'Luồng xử lý offline gồm dữ liệu Parquet, ETL Spark, core và chia tập, pipeline MLlib, artifact mô hình và bảng phục vụ. Luồng online gồm trình duyệt, Next.js, API proxy cùng origin và FastAPI. API giữ một Spark session và nạp mô hình đã huấn luyện. Yêu cầu ước tính không huấn luyện lại hoặc đọc mô tả tin nguồn.',
        'Giao diện dùng Next.js, React, TypeScript, Tailwind CSS và thành phần theo shadcn/ui mã nguồn mở, Recharts cho biểu đồ và Leaflet cho GeoJSON. Phiên bản được khóa trong package-lock.json. Hướng dùng OpenDesign hoặc cloner đã được cân nhắc; phiên bản hiện tại xây trực tiếp từ thành phần mở để phù hợp luồng phân tích. Không sao chép thương hiệu hoặc nội dung của một website bất động sản khác.',
        'Tổng quan cho phép lọc loại hình, khu vực, tháng và xuất thống kê CSV. Các trung vị được tính chính xác trên tập dòng đã lọc trong bảng Parquet gọn bằng NumPy, không lấy trung vị của các trung vị nhóm. Khám phá thị trường hiển thị xu hướng theo tháng, so sánh khu vực và bảng số lượng. Nhóm dưới 20 tin được đánh dấu ít mẫu.',
        'Bản đồ hiển thị 22 polygon lịch sử, màu theo phân vị trung vị đơn giá của loại hình và tháng được chọn. Nhấn polygon cập nhật khu vực và thống kê. Biểu mẫu ước tính có loại nhà, diện tích, quận, phường, dự án và thuộc tính tùy chọn; kết quả gồm giá, dải, coverage thực đo và cảnh báo. Hai trang còn lại công bố tất cả mô hình và phạm vi dữ liệu.',
        'Chế độ mặc định chỉ bind frontend và API tại localhost. Chế độ LAN bind frontend 0.0.0.0, API tiếp tục localhost và được truy cập qua proxy. Hệ thống dùng một worker, khóa truy cập suy luận để tránh nhiều Spark job đồng thời; khi bận trả 429 để người dùng thử lại. Đưa lên Internet là bước vận hành riêng sau local/LAN, cần host có Java và đủ RAM, reverse proxy HTTPS và quản lý truy cập. Phiên bản hiện tại chưa triển khai công khai.'
    ])
    section('13 Minh họa giao diện và kiểm tra tích hợp',[
        'Ảnh dưới chụp từ bản chạy cục bộ với dữ liệu và mô hình thật. Màn hình mặc định hiển thị 114.312 tin căn hộ sau xử lý, trung vị giá khoảng 4,85 tỷ VND và diện tích khoảng 76 m². Khi đổi bộ lọc, API tính lại thống kê đúng tập dòng được chọn. Các số này mô tả cohort, không phải toàn bộ nguồn hoặc số giao dịch.',
        'Kiểm tra API thực hiện 35 lượt gọi qua proxy web, đối chiếu count và trung vị từng bộ lọc với Parquet, tổng số dòng theo tháng và quận, 22 polygon, danh mục train, mô hình đã lưu và đầu vào sai. Các trường hợp diện tích 0 hoặc vượt giới hạn, khu vực/phường không hỗ trợ, loại hình ngoài phạm vi, trường giá đưa vào request và số phòng âm đều trả 422.',
        'Kiểm tra trình duyệt thực hiện trên desktop 1440×1000 và mobile 390×844, qua sáu màn hình, chọn tháng/quận và đối chiếu số tin, tải CSV, nhấn polygon, gửi yêu cầu dự đoán thật và dùng menu mobile. Kiểm tra cuối không ghi nhận lỗi JavaScript hoặc HTTP tài nguyên. TypeScript và production build đã chạy thành công. Các kết quả kiểm tra máy đọc lưu trong artifacts/verification.',
        'Các smoke của quy tắc, kiểm tra chéo, Parquet trên Windows, chia tập và pipeline MLlib đã chạy. Những kiểm tra này giúp phát hiện lỗi triển khai và khả năng tái sử dụng artifact, nhưng không chứng minh giá tin thật hoặc thay thế xác minh chuyên gia. Không đo chịu tải nhiều người dùng hoặc hiệu năng Internet trong phạm vi local/LAN hiện tại.'
    ],image='artifacts/verification/web/01-overview.png')
    section('14 Kết luận và hướng phát triển',[
        'Đồ án đã hoàn thành chuỗi xử lý dữ liệu thực bằng Spark, bộ quy tắc giao dịch và kiểm tra chéo có mẫu đánh giá, cohort có split thời gian và proxy xử lý đăng lại, baseline và chín pipeline lưu/nạp được, cùng web phân tích và ước tính giá từ mô hình thật. Kết quả lựa chọn là LinearRegression riêng từng loại hình; cải thiện MAE so với trung vị khu vực trên test nhưng vẫn có sai số lớn ở đuôi giá.',
        'Phương án đáp ứng yêu cầu kỹ thuật của môn học ở mức xử lý dữ liệu, công nghệ Big Data, thực nghiệm có đánh giá và ứng dụng minh họa. Phần nộp cần nhóm hoàn thiện thông tin hành chính, nhật ký và đóng góp thực tế, đồng thời xác nhận tên đề tài với giảng viên. Báo cáo không tự khẳng định tên mới đã được duyệt hoặc gán tỷ lệ công việc chưa có chứng cứ.',
        'Các mở rộng có ích là review người độc lập với mẫu nhà nhiều hơn, đối chiếu giá cực trị từ nguồn, phát hiện cùng tài sản khác nội dung, chuẩn hóa cơ sở đo diện tích và dự án, đánh giá các cửa sổ thời gian mới. Mỗi lần thay quy tắc hoặc mô hình phải tạo phiên bản và mẫu đánh giá mới, không dùng test hiện tại làm tập chọn tham số.',
        'Về triển khai, có thể chuyển pipeline lên Linux hoặc cluster và đo thời gian, tài nguyên, khả năng mở rộng bằng thực nghiệm riêng. Sản phẩm Internet cần kiểm soát truy cập và theo dõi hoạt động trước khi công bố. Hướng mở rộng không làm thay đổi cách đọc kết quả bản hiện tại: ước tính giá rao từ tập tin đã chọn và địa bàn lịch sử.'
    ])
